<?php
require __DIR__.'/../includes/learning_content.php';define('BASE_URL','/');
function check($v,$m){if(!$v)throw new RuntimeException($m);}function rejects($f){try{$f();}catch(InvalidArgumentException $e){return;}throw new RuntimeException('Expected rejection');}
foreach(['https://www.youtube.com/watch?v=M7lc1UVf-VE&x=1','https://youtu.be/M7lc1UVf-VE','https://youtube.com/shorts/M7lc1UVf-VE','https://youtube.com/live/M7lc1UVf-VE','https://www.youtube-nocookie.com/embed/M7lc1UVf-VE']as$url)check(lc_youtube($url)==='https://www.youtube-nocookie.com/embed/M7lc1UVf-VE?rel=0','Canonical YouTube');
foreach(['https://youtube.com.evil.test/watch?v=M7lc1UVf-VE','https://youtube.com/watch?v[]=M7lc1UVf-VE','javascript:alert(1)','https://user@youtube.com/watch?v=M7lc1UVf-VE','https://youtube.com/watch?v=bad']as$url)check(lc_youtube($url)==='','Reject hostile provider URL');
check(lc_vimeo('https://vimeo.com/76979871/abcdef1234')==='https://player.vimeo.com/video/76979871?h=abcdef1234','Unlisted Vimeo hash');check(lc_vimeo('https://player.vimeo.com/video/76979871?h=abcdef1234')==='https://player.vimeo.com/video/76979871?h=abcdef1234','Vimeo embed URL');
rejects(fn()=>lc_validate_choice('resource','Video','article',''));rejects(fn()=>lc_validate_choice('resource','Hình ảnh','youtube','https://youtube.com/watch?v=M7lc1UVf-VE'));rejects(fn()=>lc_validate_choice('exam','Video','upload',''));rejects(fn()=>lc_validate_choice('resource','Video','youtube','https://evil.test/'));rejects(fn()=>lc_validate_choice('resource','Video','video_url','http://example.com/v.mp4'));rejects(fn()=>lc_validate_choice('resource','Văn bản','link','javascript:alert(1)'));
rejects(fn()=>lc_validate_choice('resource','Video','video_url','https://youtube.com/watch?v=M7lc1UVf-VE'));
check(lc_validate_choice('resource','Video','youtube','https://youtu.be/M7lc1UVf-VE')==='https://youtu.be/M7lc1UVf-VE','YouTube accepted');check(lc_validate_choice('exam','Đề kiểm tra','upload','')==='','Exam upload');
check(lc_upload_mime('Video','upload','clip.mp4',"\x00\x00\x00\x18ftypmp42",'application/octet-stream')==='video/mp4','MP4 signature');rejects(fn()=>lc_upload_mime('Video','upload','clip.mp4','<script>','video/mp4'));rejects(fn()=>lc_upload_mime('Video','upload','clip.html','<video>','text/html'));rejects(fn()=>lc_upload_mime('Hình ảnh','upload','x.png','<svg>','image/png'));rejects(fn()=>lc_upload_mime('Văn bản','upload','x.html','<script>','text/html'));
$old=['id'=>'legacy','kind'=>'Video','source_kind'=>'article'];check(lc_preview($old)['src']==='/hoclieu_file.php?id=legacy','Legacy inconsistent article remains readable');
$old['source_kind']='link';$old['url']='https://youtu.be/M7lc1UVf-VE';check(lc_preview($old)['src']==='https://www.youtube-nocookie.com/embed/M7lc1UVf-VE?rel=0','Legacy YouTube links embed');
$old['source_kind']='upload';check(lc_preview($old)['mode']==='video'&&str_contains(lc_preview($old)['src'],'inline=1'),'Uploaded video uses native player');
$old['kind']='Văn bản';$old['file_path']='gdrive:abcdefghijk123';check(lc_preview($old)['src']==='https://drive.google.com/file/d/abcdefghijk123/preview','Uploaded document uses embed, not view redirect');
check(lc_byte_range('bytes=3-5',10)===[3,5],'Byte range');check(lc_byte_range('bytes=-3',10)===[7,9],'Suffix range');rejects(fn()=>lc_byte_range('bytes=99-',10));rejects(fn()=>lc_byte_range('bytes=0-1,4-5',10));
$drive='https://drive.google.com/file/d/abcdefghijk123/preview';
foreach(['https://drive.google.com/file/d/abcdefghijk123/view?usp=sharing','https://drive.google.com/open?id=abcdefghijk123','https://drive.google.com/uc?export=download&id=abcdefghijk123','https://docs.google.com/document/d/abcdefghijk123/edit','https://docs.google.com/spreadsheets/d/abcdefghijk123/edit#gid=0','https://docs.google.com/presentation/d/abcdefghijk123/present']as$url){check(lc_drive($url)===$drive,'Drive canonical preview');foreach(['link','gdrive']as$source)check(lc_preview(['id'=>'d','kind'=>'Video','source_kind'=>$source,'url'=>$url])['src']===$drive,'Legacy and explicit Drive embed');}
check(lc_drive('https://drive.google.com/file/d/abcdefghijk123/view?resourcekey=0-abc')===$drive.'?resourcekey=0-abc','Preserve resource key');
foreach(['https://drive.google.com.evil.test/file/d/abcdefghijk123/view','https://drive.google.com/drive/folders/abcdefghijk123','https://drive.google.com/open?id[]=abcdefghijk123','https://user@drive.google.com/file/d/abcdefghijk123/view','javascript:alert(1)']as$url){check(lc_drive($url)==='','Reject unsupported/hostile Drive');rejects(fn()=>lc_validate_choice('exam','Đề kiểm tra','gdrive',$url));}
foreach(lc_schema()as$kind=>$choices)check(lc_validate_choice('resource',$kind,'gdrive',$drive)===$drive,'Drive supported for resource kind');foreach(lc_schema('exam')as$kind=>$choices)check(lc_validate_choice('exam',$kind,'gdrive',$drive)===$drive,'Drive supported for exam kind');
check(lc_drive_download_url('https://drive.google.com/file/d/abcdefghijk123/view?resourcekey=0-abc')==='https://drive.google.com/uc?export=download&id=abcdefghijk123&resourcekey=0-abc','Drive download preserves key');
foreach(['document'=>'pdf','spreadsheets'=>'xlsx','presentation'=>'pptx']as$type=>$format)check(lc_drive_download_url('https://docs.google.com/'.$type.'/d/abcdefghijk123/edit')==='https://docs.google.com/'.$type.'/d/abcdefghijk123/export?format='.$format,'Google native export');
check(!lc_can_download(['source_kind'=>'article','url'=>'https://evil.test/']),'No download for articles');check(lc_drive_download_url('https://drive.google.com.evil.test/file/d/abcdefghijk123/view')==='','No download redirect to hostile URL');
